effect.shader:
const float TAU = 6.28318530718;

// ============================================================================
//  ACASO
// ============================================================================

float semente() {
    return seed * 13.71 + 1.37;
}

float hash11(float p) {
    p = fract(p * 0.1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}

float hash21(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

/** Ruído de valor 1D, -1..1, liso. */
float ruido1(float x) {
    float i = floor(x);
    float f = fract(x);
    float u = f * f * (3.0 - 2.0 * f);
    return mix(hash11(i + semente()), hash11(i + 1.0 + semente()), u) * 2.0 - 1.0;
}

float indiceDoQuadro() {
    float fd = acFrameDuration > 0.0 ? acFrameDuration : 1.0 / 30.0;
    return floor(acTime / fd + 0.5);
}

// ============================================================================
//  COR (YIQ: o NTSC separa luz e cor, e a fita trata as duas de jeitos diferentes)
// ============================================================================

float luma(vec3 c) {
    return dot(c, vec3(0.299, 0.587, 0.114));
}

vec3 paraYiq(vec3 c) {
    return vec3(
        dot(c, vec3(0.299, 0.587, 0.114)),
        dot(c, vec3(0.596, -0.274, -0.322)),
        dot(c, vec3(0.211, -0.523, 0.312)));
}

vec3 deYiq(vec3 q) {
    return vec3(
        q.x + 0.956 * q.y + 0.621 * q.z,
        q.x - 0.272 * q.y - 0.647 * q.z,
        q.x - 1.106 * q.y + 1.703 * q.z);
}

// ============================================================================
//  O QUADRO DA TELA (as barras pretas)
// ============================================================================

/**
 * A proporção da tela. "Automática" é 4:3 numa camada deitada e 3:4 numa em pé:
 * um quadro 4:3 deitado num vídeo vertical ficaria minúsculo.
 */
float proporcaoDaTela() {
    if (screenAspect == 1) return acAspect >= 1.0 ? 4.0 / 3.0 : 3.0 / 4.0;
    if (screenAspect == 2) return 4.0 / 3.0;
    if (screenAspect == 3) return 3.0 / 4.0;
    if (screenAspect == 4) return 1.0;
    if (screenAspect == 5) return 16.0 / 9.0;
    return acAspect;
}

/** O tamanho da tela dentro da camada (0..1), centrada. */
vec2 tamanhoDaTela() {
    float a = proporcaoDaTela();
    return a < acAspect ? vec2(a / acAspect, 1.0) : vec2(1.0, acAspect / max(a, 0.0001));
}

/** A imagem PREENCHE a tela (corta o que sobra), como uma TV 4:3 passando algo mais largo. */
vec2 escalaDoConteudo() {
    float a = proporcaoDaTela();
    return a < acAspect ? vec2(a / acAspect, 1.0) : vec2(1.0, acAspect / max(a, 0.0001));
}

vec2 paraTela(vec2 uv) {
    return (uv - 0.5) / tamanhoDaTela() + 0.5;
}

bool foraDe(vec2 p) {
    return p.x < 0.0 || p.y < 0.0 || p.x > 1.0 || p.y > 1.0;
}

/**
 * Onde, na tela da câmera gravada (OSD, filmado em 4:3), cai o ponto p da tela.
 *
 * Deitada: o OSD cobre a tela, como sempre. EM PÉ (relato do snow, 27/09/2026:
 * "numa composição em pé os elementos ficam meio fora da cena — o REC e tal"):
 * espremer o 4:3 numa tela 3:4 achatava o texto e tirava os cantos do lugar.
 * Agora o OSD mantém a proporção, ocupa a largura toda, e os TRÊS TERÇOS dele
 * ficam presos onde fazem sentido numa tela alta: o de cima (REC, bateria) no
 * alto, o do meio (foco, pausa) no meio, o de baixo (data, contador) embaixo.
 * Entre eles, nada. Devolve (-1, -1) para "sem OSD aqui".
 */
vec2 uvDoOsd(vec2 p) {
    vec2 tela = tamanhoDaTela();
    float aspectoDaTela = acAspect * tela.x / max(tela.y, 0.0001);
    if (aspectoDaTela >= 1.0) return p;
    float altura = 1.0 / aspectoDaTela;      // altura da tela, em larguras
    float yW = p.y * altura;
    float terco = 0.75 / 3.0;                // um terço do OSD (4:3 = 0,75 de altura por largura)
    if (yW < terco) return vec2(p.x, yW / 0.75);
    if (yW > altura - terco) return vec2(p.x, 1.0 - (altura - yW) / 0.75);
    float meio = altura * 0.5;
    if (abs(yW - meio) < terco * 0.5) return vec2(p.x, 0.5 + (yW - meio) / 0.75);
    return vec2(-1.0);
}

// ============================================================================
//  O SINAL: TUDO QUE DESLOCA A IMAGEM (em larguras da tela)
// ============================================================================

/** A energia das linhas claras do glitch filmado nesta altura. */
float energiaDoGlitch(float y) {
    if (glitchOverlay == 0) return 0.0;
    float soma = 0.0;
    float maior = 0.0;
    for (int i = 0; i < 5; i++) {
        float l = luma(texture(glitchImg, vec2(0.1 + 0.2 * float(i), y)).rgb);
        soma += l;
        maior = max(maior, l);
    }
    return clamp(maior * 0.6 + soma * 0.08, 0.0, 1.0);
}

/** A faixa de tracking: onde ela está nesta altura (0..1). */
float faixaDeTracking(float y) {
    if (tracking <= 0.0) return 0.0;
    float centro = fract(acTime * bandSpeed * 0.08 + hash11(semente() + 3.0));
    float d = abs(fract(y - centro + 0.5) - 0.5);
    return 1.0 - smoothstep(0.0, 0.05 + tracking * 0.05, d);
}

vec2 deslocamento(vec2 p) {
    float k = vhsAmount;
    float q = indiceDoQuadro();
    float s = semente();
    float linha = floor(p.y * 480.0);
    vec2 d = vec2(0.0);

    // Tremor de base de tempo: as linhas oscilam um pouco, cada uma, e o conjunto
    // ondula devagar. É o "vivo" de uma fita parada.
    d.x += jitter * k * ruido1(p.y * 60.0 + q * 0.7 + s) * 0.0022;
    d.x += jitter * k * (hash21(vec2(linha, q + s)) - 0.5) * 0.0008;

    // Pulo vertical, de vez em quando.
    if (bounce > 0.0) {
        float trecho = floor(q / 3.0);
        float pula = step(0.8, hash11(trecho * 1.7 + s));
        d.y += bounce * k * pula * (hash11(q + s + 5.0) - 0.5) * 0.012;
    }

    // Tracking: uma dobra LISA, que anda devagar — e não linhas soltas ao acaso.
    float w = faixaDeTracking(p.y);
    if (w > 0.0) {
        d.x += tracking * k * w * (ruido1(p.y * 22.0 + acTime * 5.0 + s) * 0.03 + 0.012);
    }

    // Head switching: o pé da imagem torto para a direita, com ruído.
    if (headSwitch > 0.0) {
        float pe = smoothstep(0.972, 1.0, p.y);
        d.x += headSwitch * k * pe * (0.018 + 0.03 * hash21(vec2(linha, q + s)));
    }

    // O glitch filmado rasga a imagem onde tem linha clara.
    if (glitchDisplace > 0.0 && glitchAmount > 0.0) {
        float e = energiaDoGlitch(p.y);
        d.x += glitchDisplace * glitchAmount * e * ((hash21(vec2(linha * 0.5, q + s)) - 0.5) * 0.08 + 0.02);
    }
    return d;
}

// ============================================================================
//  PASSE 0 — A FITA
// ============================================================================

vec4 amostra(vec2 c) {
    return texture(inputImg, clamp(c, 0.0, 1.0));
}

vec4 passeFita() {
    vec2 p = paraTela(acScreenNorm);
    if (foraDe(p)) return vec4(0.0);
    float k = vhsAmount;
    vec2 pd = p + deslocamento(p);
    vec2 escala = escalaDoConteudo();
    vec2 c = 0.5 + (pd - 0.5) * escala;
    // Um pixel da saída, em coordenada do conteúdo.
    float passo = acTexelSize.x / tamanhoDaTela().x * escala.x;

    // Luz: pouca nitidez na horizontal (a fita perdia resolução sobretudo aí).
    float passoLuz = softness * k * 0.5 * passo;
    float Y = luma(amostra(c).rgb) * 0.36
            + (luma(amostra(c + vec2(passoLuz, 0.0)).rgb) + luma(amostra(c - vec2(passoLuz, 0.0)).rgb)) * 0.24
            + (luma(amostra(c + vec2(passoLuz * 2.0, 0.0)).rgb) + luma(amostra(c - vec2(passoLuz * 2.0, 0.0)).rgb)) * 0.08;

    // Cor: bem mais borrada, e ATRASADA para a direita — a croma da fita
    // chega depois da luz. Sete amostras, cinco delas à esquerda (a cor que
    // aparece aqui é a que estava à esquerda).
    float passoCor = bleed * k * 0.5 * passo;
    vec2 iq = vec2(0.0);
    float Ylargo = 0.0;
    for (int i = 0; i < 7; i++) {
        vec3 q = paraYiq(amostra(c - vec2(float(i - 1) * passoCor, 0.0)).rgb);
        iq += q.yz / 7.0;
        Ylargo += q.x / 7.0;
    }

    // O contorno claro do realce: o videocassete "afiava" a imagem e deixava
    // um halo em volta das bordas.
    Y += halo * k * (Y - Ylargo);
    iq *= saturation;
    float lava = blackLift * k;
    Y = lava + Y * (1.0 - lava);

    vec3 cor = deYiq(vec3(Y, iq));
    vec3 tom = tintColor.rgb / max(luma(tintColor.rgb), 0.05);
    cor *= mix(vec3(1.0), tom, tintAmount);

    // No pé da imagem, o head switching também embaralha a cor.
    if (headSwitch > 0.0) {
        float pe = smoothstep(0.972, 1.0, p.y) * headSwitch * k;
        float r = hash21(vec2(floor(acScreenNorm.x * acResolution.x / 3.0), floor(p.y * 480.0) + indiceDoQuadro()));
        cor = mix(cor, vec3(r) * 0.8 + cor * 0.3, pe * 0.45);
    }
    return vec4(clamp(cor, 0.0, 1.0), amostra(c).a);
}

// ============================================================================
//  PASSE 1 — A TELA (o que a câmera gravou, com as barras)
// ============================================================================

vec4 passeTela() {
    vec2 uv = acScreenNorm;
    vec2 p = paraTela(uv);
    if (foraDe(p)) return vec4(barColor.rgb, 1.0);

    float k = vhsAmount;
    float q = indiceDoQuadro();
    float s = semente();

    // Aberração: o vermelho e o azul separados do verde.
    vec2 dir = vec2(1.0, 0.0);
    if (aberrationMode == 1) {
        vec2 v = (p - 0.5) * vec2(acAspect * tamanhoDaTela().x / max(tamanhoDaTela().y, 0.0001), 1.0);
        dir = length(v) > 0.0001 ? v / length(v) * min(length(v) * 2.0, 1.0) : vec2(0.0);
    }
    vec2 ab = dir * aberration * acTexelSize;
    vec4 c = texture(fita, uv);
    c.r = texture(fita, uv + ab).r;
    c.b = texture(fita, uv - ab).b;

    // A tela da câmera: o azul do fundo sai por croma, o texto fica.
    if (osdOverlay > 0 && osdOpacity > 0.0) {
        vec2 d = deslocamento(p) * osdDamage;
        vec2 base = uvDoOsd(p);
        vec2 o = (base + d - 0.5) / max(osdSize, 0.01) + 0.5;
        if (base.x >= 0.0 && !foraDe(o)) {
            vec4 t = texture(osdImg, o);
            // Gravada na fita: a cor do OSD também escorre um pouco.
            vec4 t2 = texture(osdImg, o - vec2(bleed * k * acTexelSize.x * 0.5, 0.0));
            t = mix(t, (t + t2) * 0.5, osdDamage * 0.6);
            float azul = t.b - max(t.r, t.g);
            float a = 1.0 - smoothstep(0.22, 0.5, azul);
            vec3 corOsd = t.rgb;
            corOsd.b = min(corOsd.b, max(corOsd.r, corOsd.g) + 0.08);
            c.rgb = mix(c.rgb, corOsd, a * osdOpacity);
            c.a = max(c.a, a * osdOpacity);
        }
    }

    // O glitch filmado por cima.
    if (glitchOverlay > 0 && glitchAmount > 0.0) {
        vec3 g = texture(glitchImg, p).rgb;
        if (glitchBlend == 0) {
            c.rgb = 1.0 - (1.0 - c.rgb) * (1.0 - g * glitchAmount);
        } else if (glitchBlend == 1) {
            c.rgb += g * glitchAmount;
        } else {
            vec3 sob = mix(2.0 * c.rgb * g, 1.0 - 2.0 * (1.0 - c.rgb) * (1.0 - g), step(0.5, c.rgb));
            c.rgb = mix(c.rgb, sob, glitchAmount);
        }
    }

    // Riscos de dropout dentro da faixa de tracking.
    float w = faixaDeTracking(p.y);
    if (w > 0.0) {
        float celula = floor(uv.x * acResolution.x / 14.0);
        float risco = step(0.975 - tracking * 0.03, hash21(vec2(celula, floor(p.y * 480.0) + q + s)));
        c.rgb += risco * w * tracking * k * 0.8;
    }

    // Ruído: grão de luz fino e ruído de cor em riscos horizontais (a cor da
    // fita tinha menos resolução, então o ruído dela também é mais largo).
    float nk = noiseAmount * k;
    if (nk > 0.0) {
        vec2 px = uv * acResolution;
        float grao = hash21(floor(px) + vec2(q * 13.1, q * 7.7) + s) - 0.5;
        vec2 celulaCor = floor(px / vec2(6.0, 1.0));
        vec2 ruidoCor = vec2(hash21(celulaCor + vec2(q * 3.1, s)), hash21(celulaCor + vec2(q * 5.3, s + 9.0))) - 0.5;
        vec3 y = paraYiq(c.rgb);
        y.x += grao * nk * 0.5;
        y.yz += ruidoCor * nk * 0.3;
        c.rgb = deYiq(y);
    }

    // Vinheta dentro da tela. (As linhas agora são as do tubo, no passe 2.)
    if (vignette > 0.0) {
        vec2 v = (p - 0.5) * 2.0;
        c.rgb *= 1.0 - vignette * smoothstep(0.55, 1.6, length(v * vec2(1.0, 0.9)));
    }
    return vec4(clamp(c.rgb, 0.0, 1.0), c.a);
}

// ============================================================================
//  PASSE 2 — A TV
// ============================================================================
//
//  A fita passando numa TV de tubo, na ordem em que o snow empilhou: a TV
//  recebe o sinal (horizontal e vertical soltos), olha a imagem na resolução
//  dela, e o que ela olha é o TUBO (curvatura, linhas, tremida, vinheta). Por
//  cima, o que a recepção ruim soma: listras de cor, barras de zumbido,
//  chuvisco e pontos de interferência. Os detalhes que ele deixou nos
//  padrões (pontos a 0,63, barras com nitidez 1,95, três oitavas no
//  horizontal a 1,9...) viraram constantes.

const float PI = 3.14159265359;

float sementeTv() {
    return seed * 37.0 + 140.0;
}

float hash31(vec3 p) {
    vec3 p3 = fract(p * 0.1031);
    p3 += dot(p3, p3.zyx + 31.32);
    return fract((p3.x + p3.y) * p3.z);
}

vec3 hash33(vec3 p) {
    vec3 p3 = fract(p * vec3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yxz + 33.33);
    return fract((p3.xxy + p3.yxx) * p3.zyx);
}

float ruidoTv(float x) {
    float i = floor(x);
    float f = fract(x);
    float u = f * f * (3.0 - 2.0 * f);
    float s = sementeTv();
    return mix(hash11(i + s), hash11(i + 1.0 + s), u) * 2.0 - 1.0;
}

/** Gira a fase da croma: é o que um sinal de cor fora de fase faz. */
vec3 girarCroma(vec3 c, float angulo) {
    vec3 q = paraYiq(c);
    float cs = cos(angulo);
    float sn = sin(angulo);
    q.yz = vec2(cs * q.y - sn * q.z, sn * q.y + cs * q.z);
    return deYiq(q);
}

/**
 * O tubo num ponto da camada (pré-multiplicado): a tela envergada, as linhas,
 * a tremida e a vinheta do vidro. Fora do vidro é a moldura: a cor das barras,
 * opaca.
 */
vec4 noTubo(vec2 a) {
    vec4 moldura = vec4(barColor.rgb, 1.0);
    if (foraDe(a)) return moldura;
    vec2 c = a * 2.0 - 1.0;
    vec2 b = (c + c.yx * c.yx * c * tubeCurvature) * 0.5 + 0.5;
    if (foraDe(b)) return moldura;
    vec4 t = texture(tela, b);
    vec3 rgb = t.rgb * t.a;

    // As linhas, só onde cabem (abaixo de ~2 px por par vira moiré).
    if (scanlines > 0.0) {
        float periodo = 2.0 / max(tubeLines, 1.0) * acResolution.y;
        float some = smoothstep(1.5, 2.5, periodo);
        rgb *= 1.0 - scanlines * some * (0.5 + 0.5 * sin(b.y * tubeLines * PI)) * 0.5;
    }
    // A tremida do sincronismo vertical.
    rgb *= 1.0 - flicker * (0.5 + 0.5 * sin(acTime * 47.0));
    // A vinheta do vidro. No painel há uma "Vinheta" só, a da fita: abaixo do
    // padrão dela (0,3) ela apaga a do vidro junto; acima, só a da fita cresce.
    float d = length((b - 0.5) * 2.0 * vec2(acAspect, 1.0));
    rgb *= 1.0 - tubeVignette * clamp(vignette / 0.3, 0.0, 1.0) * smoothstep(0.6, 1.6, d);
    return vec4(rgb, t.a);
}

/**
 * A imagem como a TV a vê: `tvRes` amostras, reconstruídas com interpolação
 * (sem degrau torto quando a conta não dá inteira).
 */
vec4 lerNaTv(vec2 uv, vec2 tvRes) {
    vec2 p = uv * tvRes - 0.5;
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec4 a = noTubo((i + vec2(0.5, 0.5)) / tvRes);
    vec4 b = noTubo((i + vec2(1.5, 0.5)) / tvRes);
    vec4 c = noTubo((i + vec2(0.5, 1.5)) / tvRes);
    vec4 d = noTubo((i + vec2(1.5, 1.5)) / tvRes);
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

/**
 * A faixa entre um quadro e outro, que aparece quando a imagem rola: o código
 * de tempo em blocos e a legenda oculta (a fileira de tracinhos piscando).
 */
vec3 faixaDeServico(float y, float x, vec2 tv, float quadro, vec2 tvRes) {
    float s = sementeTv();
    float total = max(floor(0.1 * tvRes.y), 1.0);
    float linha = floor(y * total);
    vec3 v = vec3(hash31(vec3(floor(tv), quadro + s)) * 0.1);
    float quadroDoSinal = floor(acTime * 30.0);
    if (abs(linha - floor(total * 0.4)) < 0.5 && x > 0.08 && x < 0.9) {
        float bloco = floor(x * 90.0);
        float muda = bloco > 60.0 ? quadroDoSinal : floor(quadroDoSinal / 30.0);
        v = vec3(step(0.5, hash21(vec2(bloco, muda + s))) * 0.75);
    }
    if (abs(linha - floor(total * 0.72)) < 0.5 && x > 0.03 && x < 0.92) {
        if (x < 0.13) {
            v = vec3(0.5 + 0.5 * sin(x * TAU * 55.0)) * 0.8;
        } else {
            float bit = floor(x * 48.0);
            v = vec3(step(0.45, hash21(vec2(bit, floor(quadroDoSinal / 2.0) + s))) * 0.85);
        }
    }
    return v;
}

vec4 passeTv() {
    vec2 uvTela = acScreenNorm;
    float s = sementeTv();
    float quadro = floor(acTime * 60.0);
    float rec = max(reception, 0.0);
    float pixelsDaTv = max(tvPixels, 8.0);
    vec2 tvRes = vec2(pixelsDaTv, pixelsDaTv / max(acAspect, 0.0001));
    vec2 tv = uvTela * tvRes;                  // a grade do aparelho (fica na tela)

    // ------------------------------------------------ desligar: a imagem encolhe
    vec2 uv = uvTela;
    float escalaX = 1.0;
    bool apagada = false;
    if (turnOff > 0.0) {
        float escalaY = mix(1.0, 0.004, pow(smoothstep(0.0, 0.55, turnOff), 0.7));
        escalaX = mix(1.0, 0.003, smoothstep(0.5, 0.9, turnOff));
        vec2 c = uv - 0.5;
        apagada = abs(c.y) > escalaY * 0.5 || abs(c.x) > escalaX * 0.5;
        uv = 0.5 + c / vec2(escalaX, escalaY);
    }
    float yDaTela = uv.y;

    // ------------------------------------------------ imagem rolando
    // O tempo em episódios de 2,5 s; "Imagem rolando" × recepção é a fração
    // deles em que o vertical solta. No padrão é zero: rolar sozinho, de tempos
    // em tempos, num efeito que se aplica e esquece, pareceria defeito do app.
    bool naFaixaV = false;
    float yNaFaixa = 0.0;
    float vAmt = clamp(vRoll * rec, 0.0, 1.0);
    if (vAmt > 0.0) {
        float duracao = 2.5;
        float episodio = floor(acTime / duracao);
        if (hash11(episodio * 3.17 + s) < vAmt) {
            float t = acTime - episodio * duracao;
            float passos = t * 2.0;
            float tranco = smoothstep(0.0, 1.0, fract(passos));
            float pos = 0.7 * (floor(passos) + tranco) / 2.0;
            pos += 0.004 * ruidoTv(t * 11.0 + episodio * 5.3);
            float w = mod(uv.y + pos, 1.1);
            if (w > 1.0) {
                naFaixaV = true;
                yNaFaixa = (w - 1.0) / 0.1;
            }
            uv.y = w;
        }
    }

    // ------------------------------------------------ horizontal solto
    bool naFaixaH = false;
    // No painel há um "Tremor" só, o das linhas: abaixo do padrão dele (0,25) ele
    // acalma o horizontal solto junto; acima, só o das linhas cresce.
    float hAmp = hHold * rec * clamp(jitter / 0.25, 0.0, 1.0);
    if (hAmp > 0.0) {
        float soma = 0.0;
        float peso = 0.0;
        float a = 1.0;
        float fr = 1.0;
        for (int o = 0; o < 3; o++) {
            soma += a * ruidoTv(yDaTela * 1.9 * 3.0 * fr + acTime * 0.9 * fr + float(o) * 19.7);
            peso += a;
            a *= 0.55;
            fr *= 2.1;
        }
        soma /= peso;
        float varia = 1.0 + 0.5 * (hash11(floor(acTime * 12.0) * 1.3 + s) * 2.0 - 1.0);
        float w = mod(uv.x + soma * hAmp * 0.06 * varia, 1.05);
        if (w > 1.0) naFaixaH = true;
        uv.x = w;
    }

    // ------------------------------------------------ a imagem recebida
    vec4 img;
    if (naFaixaV) {
        img = vec4(faixaDeServico(yNaFaixa, uv.x, tv, quadro, tvRes), 1.0);
    } else if (naFaixaH) {
        img = vec4(0.0, 0.0, 0.0, 1.0);
    } else if (tvRes.x < acResolution.x * 0.95) {
        img = lerNaTv(uv, tvRes);
    } else {
        img = noTubo(uv);
    }
    vec3 cor = img.rgb;
    float alfa = img.a;

    // ------------------------------------------------ listras de cor
    float listras = colorStripes * rec;
    if (listras > 0.0) {
        float ang = radians(160.0);
        vec2 pp = vec2((uvTela.x - 0.5) * acAspect, uvTela.y - 0.5);
        float fase = dot(pp, vec2(cos(ang), sin(ang))) * 10.0 + acTime * 3.0;
        cor = girarCroma(cor, sin(fase * TAU) * listras * PI * 0.35);
        vec3 arco = 0.5 + 0.5 * cos(TAU * (fase + vec3(0.0, 0.333, 0.667)));
        cor += (arco - 0.5) * listras * 0.2 * alfa;
    }

    // ------------------------------------------------ barras de zumbido
    // A rede elétrica vaza no sinal: faixas largas de brilho que rolam devagar,
    // e outras seis vezes mais finas por cima. A média fica no lugar.
    float zumbido = humBars * rec;
    if (zumbido > 0.0) {
        float f1 = fract(uvTela.y + acTime * 0.1);
        float m1 = 0.5 / (1.0 + 1.95 * 8.0);
        float b1 = smoothstep(0.0, m1, f1) * (1.0 - smoothstep(0.35, 0.35 + m1, f1));
        float g1 = 1.0 + zumbido * (b1 - 0.35) * 1.2;
        float f2 = fract(uvTela.y * 6.0 + acTime * 0.13);
        float b2 = smoothstep(0.0, 0.1, f2) * (1.0 - smoothstep(0.5, 0.6, f2));
        float g2 = 1.0 + zumbido * (b2 - 0.5) * 0.5;
        cor *= max(g1 * g2, 0.0);
    }

    // ------------------------------------------------ chuvisco
    // Na grade da TV, e na tela inteira: as barras pretas também chuviscam.
    float chuvisco = staticAmp * rec;
    if (chuvisco > 0.0) {
        vec3 celula = vec3(floor(tv), quadro + s);
        float tem = step(hash31(celula + vec3(0.0, 0.0, 91.3)), 0.7);
        vec3 neve = mix(vec3(hash31(celula)), hash33(celula), 0.25);
        cor += (neve - 0.5) * chuvisco * 0.9 * tem * alfa;
    }

    // ------------------------------------------------ pontos de interferência
    float interf = interference * rec;
    if (interf > 0.0) {
        vec2 tremor = (vec2(hash11(quadro * 1.31 + s), hash11(quadro * 2.77 + s)) - 0.5) * 2.0 * vec2(1.0, 0.1);
        vec2 p = tv + vec2(100.0, -10.0) * acTime + tremor;
        float fila = floor(p.y);
        float x = p.x / 9.0 + fila * 0.63;
        float celulaX = floor(x);
        float f = fract(x);
        float tem = step(hash21(vec2(celulaX, fila) + s), 0.28);
        float ponto = smoothstep(0.0, 0.06, f) * (1.0 - smoothstep(0.14, 0.26, f));
        float rajada = smoothstep(-0.2, 0.6, ruidoTv(p.y / tvRes.y * 4.0 + acTime * 0.7));
        vec3 corDoPonto = 0.35 + 0.9 * hash33(vec3(celulaX, fila, s));
        cor += corDoPonto * ponto * tem * rajada * interf * 0.8 * alfa;
    }

    // ------------------------------------------------ desligar
    // A imagem esbranquiça e desaba num risco (até 0,55), o risco vira um
    // ponto (até 0,9), e o ponto some com um clarão.
    if (turnOff > 0.0) {
        cor = mix(cor, vec3(alfa), smoothstep(0.04, 0.5, turnOff));
        if (apagada) cor = vec3(0.0);
        float apagando = smoothstep(0.3, 1.0, turnOff);
        cor *= 1.0 - apagando * apagando;
        if (turnOff < 1.0) {
            vec2 c = (uvTela - 0.5) * vec2(acAspect, 1.0);
            float quando = smoothstep(0.6, 0.88, turnOff) * (1.0 - smoothstep(0.9, 1.0, turnOff));
            float redondo = exp(-dot(c, c) / 0.0025);
            float risco = exp(-abs(c.y) / 0.006) * exp(-abs(c.x) / (0.35 * max(escalaX, 0.05)));
            cor += vec3(1.0, 0.97, 0.92) * (redondo * 0.6 + risco * 0.4) * quando * alfa;
        }
    }

    float a = clamp(alfa, 0.0, 1.0);
    vec3 rgb = clamp(cor, 0.0, max(a, 0.0001));
    return vec4(a > 0.0001 ? rgb / a : vec3(0.0), a);
}

void main() {
    if (acPass == 0) { fragColor = passeFita(); return; }
    if (acPass == 1) { fragColor = passeTela(); return; }
    fragColor = passeTv();
}
